    "Carburant : sans carburant le P.E.T reste au hangar. Achat rapide +1 000 dans la fenêtre P.E.T.": "燃料：燃料がないとP.E.Tはハンガーに留まります。P.E.Tウィンドウで +1,000 をクイック購入。",
