    "Ce tableau lit tes vraies touches : modifie-les dans Paramètres → Commandes (clique une ligne puis appuie la nouvelle touche).": "この表は実際のキー設定を読み取ります：設定 → 操作で変更できます（行をクリックしてから新しいキーを押す）。",
