    "Chaque chargement coûte 100 unités du minerai choisi. Changer de minerai remplace le stock en cours. Le chargement se fait dans la fenêtre Raffinage (onglet Upgrade) ou automatiquement (Soute du BOT).": "1回の装填で選択した鉱石を100単位消費します。鉱石を変更すると現在の在庫が置き換わります。装填は精製ウィンドウ（Upgradeタブ）または自動（BOTの貨物室）で行います。",
    "Chaque compétence a des prérequis (points investis dans d'autres compétences).": "各スキルには前提条件があります（他のスキルへの投資ポイント）。",
    "chaque famille existe en 3 forces ; Boss ≈ ×4 et Uber ≈ ×8 les gains du normal.": "各系統には3つの強さがあり、Bossは通常の約×4、Uberは約×8の獲得量です。",
    "Chaque firme a une base en X-1 et en X-8 : réparation, comptoir, zone sûre.": "各企業はX-1とX-8に基地を持ちます：修理、交易所、安全地帯。",
    "Chaque hangar a 2 configurations indépendantes : bascule avec la touche Changer configuration.": "各ハンガーには独立した構成が2つあります：構成変更キーで切り替えます。",
